package com.industrial.defect.service;
import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import com.industrial.defect.dto.keyboard.KeyboardInspectionResponse; import com.industrial.defect.entity.keyboard.*; import com.industrial.defect.exception.ResourceNotFoundException; import com.industrial.defect.repository.keyboard.*; import jakarta.persistence.criteria.Predicate; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile; import java.io.IOException; import java.util.*;
@Service public class KeyboardInspectionService {
 private final KeyboardInspectionRepository inspections; private final KeyboardDefectRepository defects; private final KeyboardAnalysisClient worker; private final ObjectMapper mapper;
 public KeyboardInspectionService(KeyboardInspectionRepository i,KeyboardDefectRepository d,KeyboardAnalysisClient w,ObjectMapper m){inspections=i;defects=d;worker=w;mapper=m;}
 @Transactional public KeyboardInspectionResponse inspect(MultipartFile file,String deviceInfo) {
  if(file==null||file.isEmpty())throw new IllegalArgumentException("Ảnh bàn phím không được để trống."); if(file.getSize()>25L*1024*1024)throw new IllegalArgumentException("Ảnh vượt quá 25 MB.");
  String type=file.getContentType(); if(type==null||!(type.equals("image/jpeg")||type.equals("image/png")||type.equals("image/webp")))throw new IllegalArgumentException("Chỉ chấp nhận ảnh JPEG, PNG hoặc WebP.");
  try { KeyboardInspectionResponse response=worker.analyze(file.getBytes()); Map<String,Object> root=response.values(); UUID id=UUID.fromString((String)root.get("inspectionId")); var entity=new KeyboardInspection(); entity.setId(id);entity.setOriginalFilename(file.getOriginalFilename());entity.setDeviceInfo(deviceInfo);entity.setStatus(text(root,"status"));entity.setSuccess(bool(root,"success"));entity.setHasDefect(bool(root,"hasDefect"));entity.setLayoutType(text(map(root,"keyboard"),"layoutType"));entity.setSourceImageUrl(text(map(root,"sourceImage"),"url"));entity.setDisplayImageUrl(text(map(root,"displayImage"),"url"));entity.setTotalMs(number(map(root,"processing"),"totalMs"));entity.setAnalysisJson(mapper.writeValueAsString(root)); inspections.save(entity); for(Object item:list(root,"defects")) persistDefect(entity,mapObject(item)); return response; } catch(IOException ex){throw new IllegalArgumentException("Không thể đọc ảnh tải lên.",ex);} catch(Exception ex){if(ex instanceof IllegalArgumentException)throw (IllegalArgumentException)ex;throw new IllegalStateException("Không thể hoàn tất kiểm tra bàn phím.",ex);}
 }
 @Transactional(readOnly=true) public KeyboardInspectionResponse get(UUID id){var entity=inspections.findById(id).orElseThrow(()->new ResourceNotFoundException("Không tìm thấy lần kiểm tra bàn phím: "+id));try{return mapper.readValue(entity.getAnalysisJson(),KeyboardInspectionResponse.class);}catch(Exception e){throw new IllegalStateException("Dữ liệu kiểm tra bàn phím đã lưu không hợp lệ.",e);}}
 @Transactional(readOnly=true) public Page<KeyboardInspectionResponse> history(int page,int size,String status,Boolean hasDefect){int safePage=Math.max(0,page),safeSize=Math.min(100,Math.max(1,size));var pageable=PageRequest.of(safePage,safeSize,Sort.by(Sort.Direction.DESC,"createdAt"));return inspections.findAll((root,q,cb)->{List<Predicate> p=new ArrayList<>();if(status!=null&&!status.isBlank())p.add(cb.equal(root.get("status"),status));if(hasDefect!=null)p.add(cb.equal(root.get("hasDefect"),hasDefect));return cb.and(p.toArray(Predicate[]::new));},pageable).map(e->{try{return mapper.readValue(e.getAnalysisJson(),KeyboardInspectionResponse.class);}catch(Exception x){throw new IllegalStateException("Dữ liệu kiểm tra bàn phím đã lưu không hợp lệ.",x);}});}
 private void persistDefect(KeyboardInspection in,Map<String,Object> d){var entity=new KeyboardDefect();entity.setInspection(in);entity.setDefectType(text(d,"type"));entity.setSeverity(text(d,"severity"));entity.setConfidence(number(d,"confidence"));entity.setKeyLabel(text(d,"keyLabel"));entity.setRowIndex(integer(d,"row"));entity.setColumnIndex(integer(d,"column"));var b=map(d,"bbox");entity.setX1(number(b,"x1"));entity.setY1(number(b,"y1"));entity.setX2(number(b,"x2"));entity.setY2(number(b,"y2"));entity.setReason(text(d,"reason"));defects.save(entity);}
 @SuppressWarnings("unchecked") private static Map<String,Object> map(Map<String,Object> v,String k){Object x=v.get(k);return x instanceof Map?(Map<String,Object>)x:Map.of();} @SuppressWarnings("unchecked") private static Map<String,Object> mapObject(Object x){return x instanceof Map?(Map<String,Object>)x:Map.of();} @SuppressWarnings("unchecked") private static List<Object> list(Map<String,Object> v,String k){Object x=v.get(k);return x instanceof List?(List<Object>)x:List.of();} private static String text(Map<String,Object> v,String k){Object x=v.get(k);return x==null?null:String.valueOf(x);} private static boolean bool(Map<String,Object> v,String k){return Boolean.TRUE.equals(v.get(k));} private static double number(Map<String,Object> v,String k){Object x=v.get(k);return x instanceof Number n?n.doubleValue():0d;} private static Integer integer(Map<String,Object> v,String k){Object x=v.get(k);return x instanceof Number n?n.intValue():null;}
}
